typedef struct {
  int *data;
  int size;
} MedianFinder;

MedianFinder *medianFinderCreate(void) {
  MedianFinder *obj = (MedianFinder *)malloc(sizeof(MedianFinder));
  obj->data = (int *)malloc(sizeof(int) * 200000);
  obj->size = 0;
  return obj;
}

void medianFinderAddNum(MedianFinder *obj, int num) {
  int i = obj->size;
  while (i > 0 && obj->data[i - 1] > num) {
    obj->data[i] = obj->data[i - 1];
    i--;
  }
  obj->data[i] = num;
  obj->size++;
}

double medianFinderFindMedian(MedianFinder *obj) {
  if (obj->size % 2 == 1) {
    return obj->data[obj->size / 2];
  }
  return (obj->data[obj->size / 2 - 1] + obj->data[obj->size / 2]) / 2.0;
}

class MedianFinder {
  priority_queue<int> lower;
  priority_queue<int, vector<int>, greater<int>> upper;

public:
  MedianFinder() {}
  void addNum(int num) {
    lower.push(num);
    upper.push(lower.top());
    lower.pop();
    if (lower.size() < upper.size()) {
      lower.push(upper.top());
      upper.pop();
    }
  }
  double findMedian() {
    if (lower.size() > upper.size()) return lower.top();
    return (lower.top() + upper.top()) / 2.0;
  }
};

type maxHeap []int
type minHeap []int

func (h maxHeap) Len() int            { return len(h) }
func (h maxHeap) Less(i, j int) bool  { return h[i] > h[j] }
func (h maxHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *maxHeap) Push(x interface{}) { *h = append(*h, x.(int)) }
func (h *maxHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func (h minHeap) Len() int            { return len(h) }
func (h minHeap) Less(i, j int) bool  { return h[i] < h[j] }
func (h minHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x interface{}) { *h = append(*h, x.(int)) }
func (h *minHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

type MedianFinder struct {
	lower *maxHeap
	upper *minHeap
}

func Constructor() MedianFinder {
	lo := &maxHeap{}
	up := &minHeap{}
	heap.Init(lo)
	heap.Init(up)
	return MedianFinder{lo, up}
}

func (m *MedianFinder) AddNum(num int) {
	heap.Push(m.lower, num)
	heap.Push(m.upper, heap.Pop(m.lower))
	if m.lower.Len() < m.upper.Len() {
		heap.Push(m.lower, heap.Pop(m.upper))
	}
}

func (m *MedianFinder) FindMedian() float64 {
	if m.lower.Len() > m.upper.Len() {
		return float64((*m.lower)[0])
	}
	return float64((*m.lower)[0]+(*m.upper)[0]) / 2.0
}

class MedianFinder {
  private PriorityQueue<Integer> lower = new PriorityQueue<>(Collections.reverseOrder());
  private PriorityQueue<Integer> upper = new PriorityQueue<>();

  public MedianFinder() {}

  public void addNum(int num) {
    lower.offer(num);
    upper.offer(lower.poll());
    if (lower.size() < upper.size()) lower.offer(upper.poll());
  }

  public double findMedian() {
    if (lower.size() > upper.size()) return lower.peek();
    return (lower.peek() + upper.peek()) / 2.0;
  }
}

class MedianFinder:
    def __init__(self):
        self.lower = []  # max-heap (negated)
        self.upper = []  # min-heap

    def addNum(self, num: int) -> None:
        heapq.heappush(self.lower, -num)
        heapq.heappush(self.upper, -heapq.heappop(self.lower))
        if len(self.lower) < len(self.upper):
            heapq.heappush(self.lower, -heapq.heappop(self.upper))

    def findMedian(self) -> float:
        if len(self.lower) > len(self.upper):
            return float(-self.lower[0])
        return (-self.lower[0] + self.upper[0]) / 2.0

impl MedianFinder {
  pub fn new() -> Self {
    MedianFinder {
      lower: BinaryHeap::new(),
      upper: BinaryHeap::new(),
    }
  }

  pub fn add_num(&mut self, num: i32) {
    self.lower.push(num);
    self.upper.push(Reverse(self.lower.pop().unwrap()));
    if self.lower.len() < self.upper.len() {
      self.lower.push(self.upper.pop().unwrap().0);
    }
  }

  pub fn find_median(&self) -> f64 {
    if self.lower.len() > self.upper.len() {
      *self.lower.peek().unwrap() as f64
    } else {
      (*self.lower.peek().unwrap() as f64 + self.upper.peek().unwrap().0 as f64) / 2.0
    }
  }
}

class MedianFinder {
  private lower: number[] = [];
  private upper: number[] = [];

  addNum(num: number): void {
    this.lower.push(num);
    this.lower.sort((a, b) => a - b);
    this.upper.push(this.lower.pop()!);
    this.upper.sort((a, b) => a - b);
    if (this.lower.length < this.upper.length) {
      this.lower.push(this.upper.shift()!);
      this.lower.sort((a, b) => a - b);
    }
  }

  findMedian(): number {
    if (this.lower.length > this.upper.length) {
      return this.lower[this.lower.length - 1];
    }
    return (this.lower[this.lower.length - 1] + this.upper[0]) / 2;
  }
}
